import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Checklist manuale — revisione della shell desktop (M8)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m8-shell-ui.md","filePath":"qa/m8-shell-ui.md"}'),n={name:"qa/m8-shell-ui.md"};function t(r,e,s,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="checklist-manuale-—-revisione-della-shell-desktop-m8" tabindex="-1">Checklist manuale — revisione della shell desktop (M8) <a class="header-anchor" href="#checklist-manuale-—-revisione-della-shell-desktop-m8" aria-label="Permalink to &quot;Checklist manuale — revisione della shell desktop (M8)&quot;">​</a></h1><p>Da eseguire sull&#39;app reale (<code>task run-desktop</code>, e <code>scripts/run-desktop-with-cloud.sh</code> per le voci cloud). Gli automatismi (vitest, Playwright su mock Wails, conformance Go e TS) coprono layout, comandi, tab, statistiche e presentazioni; qui si verifica ciò che solo una webview vera mostra. Riferimenti: ADR-0026 (shell) e ADR-0027 (slide).</p><p>Segnare <code>[x]</code> con data e sistema operativo.</p><h2 id="layout-e-tema" tabindex="-1">Layout e tema <a class="header-anchor" href="#layout-e-tema" aria-label="Permalink to &quot;Layout e tema&quot;">​</a></h2><ul><li>[ ] Intestazione, azioni rapide, barra sinistra, area editor e barra destra corrispondono al mockup; con la barra sinistra chiusa restano visibili le azioni rapide (con impostazioni e account in fondo).</li><li>[ ] Sui semafori di macOS l&#39;intestazione non copre i pulsanti e si può trascinare la finestra dalla sua parte vuota; i pulsanti non avviano il trascinamento.</li><li>[ ] Il pulsante chiaro/scuro cambia tema subito e il valore resta dopo un riavvio; «Sistema» nelle impostazioni segue ancora il tema del sistema.</li><li>[ ] Ridimensionando la finestra al minimo nulla si sovrappone e nessun pulsante esce dallo schermo; zoom dell&#39;interfaccia al 200 % utilizzabile.</li><li>[ ] Un <code>workspace.json</code> creato prima di M8 (schede <em>Tag</em> o <em>Segnalibri</em> a sinistra, <em>Struttura</em> a destra) si apre senza errori e senza perdere le schede aperte.</li><li>[ ] <strong>Angoli e raccordi (M18, 1.6):</strong> le schede hanno gli angoli superiori arrotondati e la scheda attiva si raccorda con una curva concava al contenuto, con l&#39;indicatore in alto; il corpo del pannello ha gli angoli superiori arrotondati. Controllare a occhio, nei due temi: molte schede (la barra scorre), schede bloccate, trascinamento di una scheda (<code>over</code>), split a due pannelli, e in contrasto elevato (<code>forced-colors</code>: i raccordi non compaiono, resta il contorno della scheda attiva). La verifica visiva fatta durante lo sviluppo è con screenshot nei due temi e in split, <strong>non con snapshot automatici</strong>: non c&#39;è un test di regressione visiva, e su una WebView reale resta da fare.</li><li>[ ] <strong>Stato vuoto (M18, 1.6):</strong> chiudere tutte le schede: il pannello offre <em>Nuova nota</em>, <em>Nuova lavagna</em>, <em>Nuovo disegno</em>, <em>Nuova presentazione</em> e il selettore rapido, ciascuno con la scorciatoia in uso (una scorciatoia riassegnata compare aggiornata). Con due pannelli vuoti, un clic apre il file nel pannello cliccato. Con una funzione spenta dal profilo la voce non compare; su un vault in sola lettura le voci che creano sono disabilitate. Nessun elemento ha il focus all&#39;apertura.</li></ul><h2 id="azioni-rapide" tabindex="-1">Azioni rapide <a class="header-anchor" href="#azioni-rapide" aria-label="Permalink to &quot;Azioni rapide&quot;">​</a></h2><ul><li>[ ] Esplora file: niente pulsanti «nuova nota/cartella» sopra l&#39;albero (restano nel menu contestuale e nelle azioni rapide); le cartelle hanno l&#39;icona chiusa/aperta.</li><li>[ ] Nuova cartella, nota, lavagna, disegno e base creano il file dove ci si aspetta (cartella configurata o cartella della nota aperta) e lo aprono.</li><li>[ ] <em>Separatore</em> inserisce <code>---</code> sotto la riga corrente con una riga vuota prima, e non trasforma il testo sopra in titolo; è disabilitato in vista lettura e su un vault di sola lettura.</li><li>[ ] <em>Esporta in PDF</em> apre il dialogo di stampa; <em>Esporta come immagine</em> salva un PNG leggibile (formule, immagini, diagrammi inclusi). <strong>Verifica in WKWebView, WebView2 e WebKitGTK</strong>: se il canvas risulta «tainted» il comando mostra un errore invece del file.</li></ul><h2 id="schede" tabindex="-1">Schede <a class="header-anchor" href="#schede" aria-label="Permalink to &quot;Schede&quot;">​</a></h2><ul><li>[ ] Blocca/Sblocca dal menu della scheda: la scheda bloccata mostra la puntina, non si chiude con ✕, clic centrale, <code>Canc</code>, <code>Mod+W</code> né con le chiusure di massa; aprendo un&#39;altra nota dall&#39;albero questa va in una scheda nuova.</li><li>[ ] Chiudi a destra, a sinistra, altre, tutte: le voci che non chiuderebbero nulla sono disabilitate; le schede bloccate restano.</li><li>[ ] Eliminando il file di una scheda bloccata, la scheda si chiude.</li><li>[ ] Dopo un riavvio le schede bloccate sono ancora bloccate.</li></ul><h2 id="barre-laterali" tabindex="-1">Barre laterali <a class="header-anchor" href="#barre-laterali" aria-label="Permalink to &quot;Barre laterali&quot;">​</a></h2><ul><li>[ ] Sinistra: <em>File</em> e <em>Struttura</em>; la lente in alto apre la ricerca come terza scheda (<code>Mod+Maiusc+F</code>); un tag cliccato filtra la ricerca.</li><li>[ ] Destra (icone con suggerimento): <em>Proprietà</em>, <em>Tag</em>, <em>Link</em> (link in uscita, backlink, segnalibri), <em>Slide</em>, <em>Statistiche</em>; i segnalibri aggiunti dal menu del file compaiono nella scheda <em>Link</em>.</li><li>[ ] <em>Statistiche</em>: date, versioni locali, dimensione e conteggi sono plausibili; la data di creazione senza ora (<code>created: 2025-05-04</code>) non scivola di giorno in nessun fuso orario; il segno «≈» compare solo quando manca <code>created</code>.</li><li>[ ] <em>Statistiche</em> su un vault condiviso collegato: versioni cloud, autore dell&#39;ultima revisione, elenco di utenti e gruppi con il livello; su un mount: «Condiviso da…»; su un vault privato: «non condivisibile».</li><li>[ ] Lo stato del vault (indicizzazione, sync, permesso, aggiornamento, inviti) è in fondo alla barra destra e passa nell&#39;intestazione quando la barra si chiude; l&#39;indicatore di sincronizzazione continua a essere annunciato dallo screen reader.</li></ul><h2 id="vault-e-account" tabindex="-1">Vault e account <a class="header-anchor" href="#vault-e-account" aria-label="Permalink to &quot;Vault e account&quot;">​</a></h2><ul><li>[ ] In fondo alla barra sinistra: nome e numero di note; il menu elenca i vault recenti (senza quello aperto); sceglierne uno lo apre, salva prima il workspace del vecchio e il vecchio si chiude (nessuna modifica persa, anche con una modifica fatta meno di un secondo prima).</li><li>[ ] «Apri un&#39;altra cartella…» apre il selettore di sistema; «Chiudi vault» torna alla schermata iniziale. Il comando <em>Cambia vault</em> apre il menu anche a barra sinistra chiusa.</li><li>[ ] Con un vault collegato compare «Privato» o «Condiviso» accanto al nome.</li><li>[ ] Senza accesso: <em>Accedi</em> in fondo alle azioni rapide apre il browser di sistema; dopo il login compaiono le iniziali; il menu offre <em>Account e dispositivi…</em> ed <em>Esci</em>.</li><li>[ ] Senza server noto, <em>Accedi</em> apre le impostazioni cloud; con il server noto non chiede nulla.</li><li>[ ] Spegnendo il server o la rete dopo l&#39;accesso: l&#39;avatar ha il bordo di avviso, il suggerimento dice «disconnesso» e il menu offre <em>Riconnetti</em>.</li></ul><h2 id="presentazioni-adr-0027" tabindex="-1">Presentazioni (ADR-0027) <a class="header-anchor" href="#presentazioni-adr-0027" aria-label="Permalink to &quot;Presentazioni (ADR-0027)&quot;">​</a></h2><ul><li>[ ] Una nota con <code>---</code>, note <code>Note:</code> e opzioni nel frontmatter: la scheda <em>Slide</em> mostra una miniatura per slide, con titolo corretto; cambiare transizione/tema/opzioni riscrive il frontmatter senza perdere altre proprietà né il cursore.</li><li>[ ] <em>Avvia la presentazione</em> e <em>Dalla slide corrente</em> partono dalla slide giusta; frecce, <code>Spazio</code>, <code>Home</code>/<code>Fine</code>, clic, <code>P</code>, <code>Esc</code> funzionano; le slide con immagini, formule, Mermaid e callout si vedono come in vista lettura.</li><li>[ ] Schermo intero in WKWebView, WebView2 e WebKitGTK: se il sistema lo nega la presentazione occupa comunque tutta la finestra; uscendo dallo schermo intero con <code>Esc</code> del sistema la presentazione termina.</li><li>[ ] Le transizioni sono disattivate con «riduci movimento» attivo nel sistema; il tema chiaro/scuro/automatico delle slide è corretto con entrambi i temi dell&#39;app.</li><li>[ ] Con la rete scollegata la presentazione funziona uguale (nessuna richiesta esterna).</li><li>[ ] Su un vault condiviso in sola lettura: si può presentare, le opzioni sono disabilitate.</li><li>[ ] Un vault creato con altri editor e con plugin di slide: le note con <code>---</code> si aprono normalmente in quegli editor e le chiavi <code>slide-*</code> e <code>Note:</code> non rompono nulla.</li></ul><h2 id="barra-di-stato-adr-0035" tabindex="-1">Barra di stato (ADR-0035) <a class="header-anchor" href="#barra-di-stato-adr-0035" aria-label="Permalink to &quot;Barra di stato (ADR-0035)&quot;">​</a></h2><ul><li>[ ] Per default non c&#39;è: nessuna riga sotto l&#39;editor. <em>Impostazioni → Aspetto → Barra di stato</em> e il comando <em>Mostra/nascondi barra di stato</em> la accendono e la spengono; la scelta resta in <code>.memobrain/appearance.json</code> alla riapertura del vault.</li><li>[ ] Su una nota: parole e caratteri come nella scheda <em>Statistiche</em> (senza il frontmatter), con una selezione i conteggi della selezione al loro posto; riga:colonna segue il cursore ed è giusta appena si apre una scheda o si passa a un altro pannello; in vista Lettura niente riga:colonna.</li><li>[ ] Il clic sulla modalità passa Live → Sorgente → Lettura → Live; su disegno, lavagna, base e grafo compare solo il tipo; senza schede la barra è vuota.</li><li>[ ] Altezza dell&#39;area editor corretta con barra e slot della chat accesi insieme (la barra sta sopra la chat); la barra non attraversa le barre laterali; sparisce durante una presentazione <em>Slide</em> e del disegno.</li><li>[ ] Con <code>appearance.statusBar</code> bloccato in un profilo di configurazione il controllo è disabilitato con «gestito dall&#39;amministratore» e il comando non la cambia.</li></ul><h2 id="chat-slot" tabindex="-1">Chat (slot) <a class="header-anchor" href="#chat-slot" aria-label="Permalink to &quot;Chat (slot)&quot;">​</a></h2><ul><li>[ ] Per default non si vede nulla sotto l&#39;editor. Con <code>features.chat=true</code> in un profilo di configurazione compare un campo disabilitato con la spiegazione «non ancora disponibile»; con <code>false</code> sparisce.</li></ul><h2 id="accessibilita" tabindex="-1">Accessibilità <a class="header-anchor" href="#accessibilita" aria-label="Permalink to &quot;Accessibilità&quot;">​</a></h2><ul><li>[ ] Con VoiceOver/NVDA: le azioni rapide, l&#39;intestazione e le schede a icona della barra destra hanno un nome parlante; una scheda bloccata è letta come «… (bloccata)»; il menu del vault e quello dell&#39;account si usano con le frecce e <code>Esc</code> rimette il focus sul pulsante.</li><li>[ ] La presentazione annuncia «Slide n di m» a ogni cambio e il focus resta dentro finché non si esce.</li><li>[ ] Contrasto elevato e tema scuro: avatar, puntina delle schede bloccate e bordo di avviso sono distinguibili.</li></ul>',21)])])}const h=a(n,[["render",t]]);export{p as __pageData,h as default};
